#!/usr/bin/env python3
# Curate Mahaperiyava / Deivathin Kural Volume 1 batch 024..045.
#
# Run from pramana repo root on branch:
#   mahaperiyava-dk-v1-corpus
#
# Recommended:
#   python ~/Downloads/curate_mahaperiyava_dk_v1_batch_024_045.py --commit --push
#
# This semantic curation pass creates 130 metadata-only teaching units across
# 20 chapters. All authority remains dk_attested. Exact DK text remains private.
# Four editorial/apparatus source blocks are explicitly excluded from teaching
# units rather than forced into artificial claims.

from __future__ import annotations

import argparse
import base64
from collections import Counter, defaultdict
from datetime import datetime, timezone
import hashlib
import json
from pathlib import Path
import re
import shutil
import subprocess
import sys
from typing import Any

ROOT = Path.cwd()
EXPECTED_BRANCH = "mahaperiyava-dk-v1-corpus"

PRIVATE_PACKET = ROOT / "data/private/mahaperiyava_dk_v1_batch_024_045_review_packet.json"
SCHEMA = ROOT / "schema/teaching_record.schema.json"
CATALOG = ROOT / "data/review/mahaperiyava_deivathin_kural_v1_catalog.json"
QUEUE = ROOT / "data/review/mahaperiyava_deivathin_kural_v1_extraction_queue.jsonl"

TEACHING_RECORDS = ROOT / "data/review/mahaperiyava_dk_v1_batch_024_045_teaching_records.jsonl"
CURATION_INDEX = ROOT / "data/review/mahaperiyava_dk_v1_batch_024_045_curation_index.json"
RESEARCH_MD = ROOT / "data/research/mahaperiyava_dk_v1_batch_024_045_teaching_units.md"
TEST = ROOT / "tests/test_mahaperiyava_dk_v1_batch_024_045_teaching_records.py"
REPO_SCRIPT = ROOT / "scripts/curate_mahaperiyava_dk_v1_batch_024_045.py"

PAYLOAD_B64 = ""
PAYLOAD = json.loads(base64.b64decode(PAYLOAD_B64).decode("utf-8"))

CURATED_UNITS = PAYLOAD["units"]
EXPECTED_PACKET_SHA256 = PAYLOAD["packet_sha"]
EXPECTED_ORDINALS = [int(x) for x in PAYLOAD["expected_ordinals"]]
EXPECTED_UNIT_COUNTS = {int(k): v for k, v in PAYLOAD["expected_unit_counts"].items()}
EXPECTED_UNIT_COUNT = 130

EXCLUDED_BLOCKS = []
for ordinal_text, mapping in PAYLOAD["excluded"].items():
    ordinal = int(ordinal_text)
    for paragraph_id, reason in mapping.items():
        EXCLUDED_BLOCKS.append(
            {
                "chapter_ordinal": ordinal,
                "paragraph_id": paragraph_id,
                "reason": reason,
            }
        )

MANAGED = [
    TEACHING_RECORDS,
    CURATION_INDEX,
    RESEARCH_MD,
    TEST,
    CATALOG,
    QUEUE,
    REPO_SCRIPT,
]


def die(message: str) -> None:
    raise SystemExit(f"ERROR: {message}")


def sh(cmd: list[str], *, capture: bool = False, check: bool = True):
    print("+", " ".join(cmd))
    return subprocess.run(
        cmd,
        cwd=ROOT,
        text=True,
        capture_output=capture,
        check=check,
    )


def now_iso() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def load_json(path: Path) -> Any:
    if not path.exists():
        die(f"Missing expected file: {path.relative_to(ROOT)}")
    return json.loads(path.read_text(encoding="utf-8"))


def load_jsonl(path: Path) -> list[dict[str, Any]]:
    if not path.exists():
        die(f"Missing expected file: {path.relative_to(ROOT)}")
    return [
        json.loads(line)
        for line in path.read_text(encoding="utf-8").splitlines()
        if line.strip()
    ]


def write_json(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        json.dumps(value, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )


def write_jsonl(path: Path, rows: list[dict[str, Any]]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8") as handle:
        for row in rows:
            handle.write(json.dumps(row, ensure_ascii=False) + "\n")


def ensure_repo_state() -> None:
    if not (ROOT / ".git").exists():
        die("Run this script from the pramana repo root.")

    branch = sh(["git", "branch", "--show-current"], capture=True).stdout.strip()
    if branch != EXPECTED_BRANCH:
        die(f"Expected branch {EXPECTED_BRANCH!r}; found {branch!r}")

    dirty = sh(["git", "status", "--porcelain"], capture=True).stdout.strip()
    if dirty:
        die("Working tree must be clean before curation.\n" + dirty)

    for path in (PRIVATE_PACKET, SCHEMA, CATALOG, QUEUE):
        if not path.exists():
            die(f"Missing required input: {path.relative_to(ROOT)}")

    if TEACHING_RECORDS.exists() or CURATION_INDEX.exists():
        die("Batch 024..045 artifacts already exist; refusing a second application.")


def validate_packet(packet: dict[str, Any]) -> dict[str, Any]:
    actual_sha = hashlib.sha256(PRIVATE_PACKET.read_bytes()).hexdigest()
    if actual_sha != EXPECTED_PACKET_SHA256:
        die(
            "Private packet SHA drifted.\n"
            f"expected {EXPECTED_PACKET_SHA256}\nactual   {actual_sha}"
        )

    if packet.get("packet_version") != "1.0":
        die("Expected private packet version 1.0.")
    if packet.get("rights", {}).get("public_export_allowed") is not False:
        die("Private source rights gate is not fail-closed.")

    selection = packet.get("selection", {})
    if (
        selection.get("selected_count") != 20
        or selection.get("start_ordinal") != 24
        or selection.get("end_ordinal") != 45
    ):
        die("Unexpected batch selection metadata.")

    by_ordinal = {c["ordinal"]: c for c in packet["chapters"]}
    if sorted(by_ordinal) != sorted(EXPECTED_ORDINALS):
        die(
            f"Unexpected chapter set: expected={EXPECTED_ORDINALS} "
            f"actual={sorted(by_ordinal)}"
        )

    if len(CURATED_UNITS) != EXPECTED_UNIT_COUNT:
        die(f"Expected 130 units; found {len(CURATED_UNITS)}")
    if len({u["id"] for u in CURATED_UNITS}) != EXPECTED_UNIT_COUNT:
        die("Teaching-unit IDs are not unique.")

    # Build hash-complete exclusion rows from the private packet.
    exclusion_keys = {
        (x["chapter_ordinal"], x["paragraph_id"])
        for x in EXCLUDED_BLOCKS
    }
    if exclusion_keys != {
        (34, "p017"),
        (39, "p042"),
        (42, "p023"),
        (42, "p024"),
    }:
        die(f"Unexpected exclusion set: {sorted(exclusion_keys)}")

    excluded_complete = []
    for item in EXCLUDED_BLOCKS:
        chapter = by_ordinal[item["chapter_ordinal"]]
        para_map = {p["id"]: p for p in chapter["paragraphs"]}
        paragraph = para_map.get(item["paragraph_id"])
        if not paragraph:
            die(
                f"Excluded source block missing: "
                f"{item['chapter_ordinal']}:{item['paragraph_id']}"
            )
        excluded_complete.append(
            {
                **item,
                "paragraph_sha256": paragraph["sha256"],
            }
        )

    # Verify all curated source hashes.
    used: dict[int, set[str]] = defaultdict(set)
    for unit in CURATED_UNITS:
        if unit["proposed_authority"] != "dk_attested":
            die(f"Unexpected authority promotion in {unit['id']}")
        if unit.get("historical_witness") is not None:
            die(f"Unexpected historical witness in {unit['id']}")

        chapter = by_ordinal[unit["chapter_ordinal"]]
        para_map = {p["id"]: p for p in chapter["paragraphs"]}

        if len(unit["source_paragraph_ids"]) != len(unit["source_paragraph_hashes"]):
            die(f"Paragraph id/hash mismatch in {unit['id']}")

        for pid, expected_hash in zip(
            unit["source_paragraph_ids"],
            unit["source_paragraph_hashes"],
        ):
            if (unit["chapter_ordinal"], pid) in exclusion_keys:
                die(f"Excluded apparatus used as teaching evidence: {unit['id']}:{pid}")
            paragraph = para_map.get(pid)
            if not paragraph:
                die(f"Missing paragraph {unit['chapter_ordinal']}:{pid}")
            if paragraph["sha256"] != expected_hash:
                die(
                    f"Paragraph hash drift for {unit['id']}:{pid}\n"
                    f"expected {expected_hash}\nactual   {paragraph['sha256']}"
                )
            used[unit["chapter_ordinal"]].add(pid)

    excluded_by_chapter: dict[int, set[str]] = defaultdict(set)
    for item in excluded_complete:
        excluded_by_chapter[item["chapter_ordinal"]].add(item["paragraph_id"])

    # No silent source gaps.
    for ordinal, chapter in by_ordinal.items():
        all_ids = {p["id"] for p in chapter["paragraphs"]}
        accounted = used[ordinal] | excluded_by_chapter[ordinal]
        if all_ids != accounted:
            die(
                f"Source coverage mismatch for {ordinal}: "
                f"missing={sorted(all_ids-accounted)} "
                f"extra={sorted(accounted-all_ids)}"
            )

    return {
        "packet_sha256": actual_sha,
        "generated_at": packet.get("generated_at"),
        "chapter_count": packet["chapter_count"],
        "paragraph_count": packet["paragraph_count"],
        "by_ordinal": by_ordinal,
        "excluded_complete": excluded_complete,
    }


