def schema_shape_validate(records: list[dict[str, Any]]) -> None:
    schema = load_json(SCHEMA)
    allowed = set(schema["properties"])
    required = set(schema["required"])
    id_re = re.compile(schema["properties"]["id"]["pattern"])

    for record in records:
        if required - set(record):
            die(f"Missing schema fields in {record['id']}: {sorted(required-set(record))}")
        if set(record) - allowed:
            die(f"Extra schema fields in {record['id']}: {sorted(set(record)-allowed)}")
        if not id_re.match(record["id"]):
            die(f"Invalid teaching-record ID: {record['id']}")

        for field in ("source_locus", "attribution", "evidence_status", "rights"):
            spec = schema["properties"][field]
            obj = record[field]
            inner_required = set(spec.get("required", []))
            inner_allowed = set(spec.get("properties", {}))
            if inner_required - set(obj):
                die(f"{record['id']}.{field} missing {sorted(inner_required-set(obj))}")
            if spec.get("additionalProperties") is False and set(obj)-inner_allowed:
                die(f"{record['id']}.{field} extra {sorted(set(obj)-inner_allowed)}")

        if record["evidence_status"] != {
            "digital_attestation": "confirmed",
            "print_check": "not_checked",
            "primary_source_status": "unknown",
            "authority": "dk_attested",
        }:
            die(f"Evidence state drift in {record['id']}")
        if record["attribution"]["wording_status"] != "dk_wording_only":
            die(f"Wording state drift in {record['id']}")


